"""Local-only source inventory, no network or payload artifact.

Uses existing1MiB SQLite bound,120s scan/130s child watchdog,640MiB canonical
row envelopes and1million source rows. Wire validation limits are unchanged.
"""
import json
from pathlib import Path
import subprocess
import sys
import time
import threading
sys.path.insert(0,str(Path(__file__).resolve().parents[2]))
from backend.cloud_snapshot import inventory_snapshot, PreparationError


def measure(path, *, validator_command=None, wall_seconds=130):
    started=time.monotonic()
    process=subprocess.Popen(validator_command or ['node',str(Path(__file__).with_suffix('.mjs'))],
        stdin=subprocess.PIPE,stdout=subprocess.PIPE,stderr=subprocess.PIPE,text=True)
    # Bound a stalled validator/pipe too, not only SQLite/row processing.
    expired=threading.Event()
    def expire():
        expired.set()
        if process.poll() is None: process.kill()
    watchdog=threading.Timer(wall_seconds,expire)
    watchdog.daemon=True;watchdog.start()
    def inspect(body):
        if process.poll() is not None: raise PreparationError('local_validator_stopped')
        process.stdin.write(body+'\n')
        process.stdin.flush()
    try:
        result=inventory_snapshot(path,inspect)
        process.stdin.close();process.stdin=None
        out,_=process.communicate(timeout=10)
        verified=json.loads(out)
        if process.returncode or verified.get('validator')!='inventory_complete':
            raise PreparationError('local_shared_validator_failed')
        if {k:v for k,v in result['rowCounts'].items() if v} != verified['rowCounts'] and not result['sourceIssues']:
            raise PreparationError('local_inventory_count_mismatch')
        verified['encodedRowCounts']=verified.pop('rowCounts')
        result.update(verified)
        result['sourceCompleteness']=not result['sourceIssues'] and verified['sharedValidationSafe']
        result['localSourceScanComplete']=result['sourceCompleteness']
        result['status']='complete_local_source_inventory' if result['sourceCompleteness'] else 'incomplete_source_inventory'
        if not result['sourceCompleteness']:
            result.pop('canonicalSourceDigest',None)
        for table, count in result['rowCounts'].items():
            stats=result['wireCompatibility']['tables'].setdefault(table,{'encoded':0,'fit':0,'blocked':0,'reasons':{},'examples':[]})
            stats['source']=count
            stats['unencoded']=count-stats['encoded']
            if stats['unencoded']<0:
                raise PreparationError('local_inventory_count_mismatch')
            stats['blocked']+=stats['unencoded']
            if stats['unencoded']:
                stats['reasons']['source_rejected']=stats['unencoded']
            if stats['fit']+stats['blocked']!=count:
                raise PreparationError('local_inventory_count_mismatch')
        result['wireCompatibility']['allRowsFit']=result['sourceCompleteness'] and result['wireCompatibility']['allRowsFit']
        result['uploadReady']=False
        result['elapsedSeconds']=round(time.monotonic()-started,3)
        result['cloudUpload']=False
        return result
    except PreparationError as error:
        return {'status':'blocked_incomplete_measurement','code':str(error),
            'diagnostics':error.diagnostics,'elapsedSeconds':round(time.monotonic()-started,3),'cloudUpload':False}
    except Exception:
        return {'status':'blocked_incomplete_measurement','code':'local_measurement_wall_timeout' if expired.is_set() else 'local_measurement_failed','cloudUpload':False}
    finally:
        watchdog.cancel()
        if process.poll() is None: process.kill()
        if process.stdin is not None:
            try: process.stdin.close()
            except (BrokenPipeError, OSError): pass
            process.stdin=None
        try: process.communicate(timeout=3)
        except subprocess.TimeoutExpired:
            process.kill();process.wait(timeout=3)

if __name__=='__main__':
    if len(sys.argv)!=2 or sys.version_info<(3,13):
        raise SystemExit('Use existing project Python3.13+ and the exact verified backup path.')
    result=measure(Path(sys.argv[1]))
    print(json.dumps(result,separators=(',',':')))
    raise SystemExit(0 if result.get('sourceCompleteness') else 2)

// Local-only canonical row inventory. No network or payload retention.
import readline from 'node:readline';
import crypto from 'node:crypto';
import {validatePart} from '../../cloud/library/part.mjs';
const hash=crypto.createHash('sha256');
const tables={}; let canonicalBytes=0,maxRowBytes=0,maxNodes=0,maxDepth=0,maxArray=0;
const coverage={'2026-11-06':{sessions:0,durationSeconds:0,openSessions:0},'2026-11-07':{sessions:0,durationSeconds:0,openSessions:0}};
const dayOf=new Intl.DateTimeFormat('en-CA',{timeZone:'America/New_York',year:'numeric',month:'2-digit',day:'2-digit'});
const allowed=new Set(['structured_metadata_limit','structured_metadata_string','structured_metadata_field','structured_metadata_invalid','part_schema_invalid','row_invalid','metadata_field_not_allowed','metadata_value_invalid']);
let unsafe=false;
function instant(v){if(v===null||v===undefined)return null;if(typeof v!=='string')throw Error();const n=new Date(/Z$|[+-]\d\d:\d\d$/.test(v)?v:v+'Z').getTime();if(!Number.isFinite(n))throw Error();return n;}
try{
 for await(const line of readline.createInterface({input:process.stdin,crlfDelay:Infinity})){
  if(Buffer.byteLength(line)>8*1024*1024)throw Error();
  const frame=JSON.parse(line),part=frame.part,row=part.rows[0],table=part.table;const ordinal=frame.rowOrdinal;
  const stats=tables[table]??={encoded:0,fit:0,blocked:0,reasons:{},examples:[]};stats.encoded++;
  const body=JSON.stringify(part),bytes=Buffer.byteLength(body),rowBytes=Buffer.byteLength(JSON.stringify(row));
  hash.update(String(bytes)+':');hash.update(body);canonicalBytes+=bytes;
  if(canonicalBytes>640*1024*1024)throw Error();
  let nodes=1+Object.keys(row).length,depthMax=0,arrayMax=0;const reasons=new Set();
  for(const [key,value]of Object.entries(row))if(key.endsWith('_json')){
   const queue=[[value,0]];
   while(queue.length){const [v,depth]=queue.pop();nodes++;depthMax=Math.max(depthMax,depth);
    if(Array.isArray(v)){arrayMax=Math.max(arrayMax,v.length);for(const x of v)queue.push([x,depth+1]);}
    else if(v&&typeof v==='object')for(const x of Object.values(v))queue.push([x,depth+1]);
   }
  }
  if(bytes>262144)reasons.add('part_bytes');
  if(rowBytes+101>250000)reasons.add('python_row_bytes');
  if(nodes>20000)reasons.add('nodes');if(depthMax>16)reasons.add('depth');if(arrayMax>4096)reasons.add('array_length');
  try{validatePart(part);}catch(error){
   const code=allowed.has(error?.code)?error.code:'unknown_validator_failure';
   reasons.add(code);if(code!=='structured_metadata_limit')unsafe=true;
   // A structural rejection may mask a later forbidden key/string. Validate
   // every nested node shallowly with the same shared validator, never use
   // these probes as transported fragments or as a replacement for the row.
   if(code==='structured_metadata_limit')for(const [column,value]of Object.entries(row)){
    if(!column.endsWith('_json'))continue;
    const queue=[value];
    function checkProbe(probe){
     try{validatePart({schema:part.schema,table,rows:[{[column]:probe}]});}
     catch(e){const c=allowed.has(e?.code)?e.code:'unknown_validator_failure';reasons.add(c);unsafe=true;}
    }
    while(queue.length){const v=queue.pop();
     if(Array.isArray(v)){checkProbe([]);for(const x of v)queue.push(x);}
     else if(v&&typeof v==='object'){
      checkProbe(Object.create(null));
      for(const [k,x]of Object.entries(v)){
       // One own key at a time, preserving even __proto__. Never allow a
       // structural probe error to hide a forbidden key or primitive.
       checkProbe(Object.fromEntries([[k,null]]));queue.push(x);
      }
     }else checkProbe(v);
    }
   }
  }
  maxRowBytes=Math.max(maxRowBytes,rowBytes);maxNodes=Math.max(maxNodes,nodes);maxDepth=Math.max(maxDepth,depthMax);maxArray=Math.max(maxArray,arrayMax);
  if(reasons.size){stats.blocked++;for(const code of reasons)stats.reasons[code]=(stats.reasons[code]??0)+1;if(stats.examples.length<5)stats.examples.push(ordinal);}
  else stats.fit++;
  if(table==='sessions'){
   try{const start=instant(row.started_at),end=instant(row.ended_at);if(start!==null){const day=dayOf.format(new Date(start));if(Object.hasOwn(coverage,day)){const c=coverage[day];c.sessions++;if(end===null)c.openSessions++;else{if(end<start)throw Error();c.durationSeconds+=(end-start)/1000;}}}}
   catch{unsafe=true;stats.reasons.invalid_session_time=(stats.reasons.invalid_session_time??0)+1;}
  }
 }
 console.log(JSON.stringify({validator:'inventory_complete',rowCounts:Object.fromEntries(Object.entries(tables).map(([t,s])=>[t,s.encoded])),wireCompatibility:{allRowsFit:Object.values(tables).every(s=>s.blocked===0),tables},canonicalRowEnvelopeBytes:canonicalBytes,largestRowBytes:maxRowBytes,largestRowNodes:maxNodes,largestDepth:maxDepth,largestArray:maxArray,canonicalSourceDigest:hash.digest('hex'),includedSessionStartsNewYork:coverage,sharedValidationSafe:!unsafe,examplesCappedAt:5,examplesMayBeCapped:Object.values(tables).some(s=>s.blocked>5),uploadReady:false}));
}catch{console.log(JSON.stringify({validator:'failed',code:'local_inventory_validation_failed'}));process.exitCode=2;}
